    '1aa36213cb676fd5baad5edc2bee4fbe117a778b' => ['name' => 'Ricercatore (Alleanza)', 'description' => 'Velocità per raggiungere la destinazione: +10%Pianeti più grandi quando si colonizza: +5%Accesso alla Falange del sistema: permette di scansionare i movimenti delle flotte nell`intero sistema (per 40.000 unità di Deuterio), a patto che queste si trovino nella portata della falange.', 'duration_label' => 'Permanente', 'extended_description' => 'Dalla sinergia delle migliori teste nascono le scoperte più importanti. Un`alleanza di ricercatori è in grado di individuare i migliori pianeti da colonizzare. Inoltre, le loro navi sono particolarmente veloci durante le spedizioni. Insieme, i ricercatori possono accedere alla Falange del sistema, tramite la quale possono scansionare i movimenti delle flotte nell`intero sistema.'],
    'c19f0e09d862d93d7956beb3185d9ee929b5ef74' => ['name' => 'KRAKEN Platino (Forme di vita)', 'description' => 'Fa diminuire (-1g) il tempo di costruzione degli edifici attualmente in costruzione su un pianeta.', 'duration_label' => 'ora'],
    '1808bf7639b81ac3ac87bcb7eb3bbba0a1874d0a' => ['name' => 'Slot flotte Oro', 'description' => '+6 Slot flotte extra', 'duration_label' => '12s 6g', 'extended_description' => 'Grazie a questo Slot flotte extra potrai far salpare un`altra flotta contemporaneamente. I generali competenti comprendono quanto sia importante incrementare la loro influenza ed estendere i loro domini nell`universo.'],
    '6c9fe5e35bdad0d4e3382eb6a5aeac6bc8263752' => ['name' => 'Mercante (Alleanza)', 'description' => 'Velocità Cargo: +10%Produzione di energia e risorse: +5%Capienza deposito su luna e pianeti: +10%', 'duration_label' => 'Permanente', 'extended_description' => 'Le alleanze commerciali sono vantaggiose per tutte le parti coinvolte, e questo l`Alleanza dei Mercanti lo sa bene. I loro Cargo sono molto veloci e i processi di produzione di energia e risorse sono stati ottimizzati. Ciò ha permesso di incrementare i guadagni. Grazie al miglioramento della logistica sono in grado di stoccare ancora più risorse sui loro pianeti e le loro lune.'],
    '00b42f7113d81f98df865bbfa2280fe3a4465e89' => ['name' => 'KRAKEN Bronzo (Forme di vita)', 'description' => 'Fa diminuire (-30m) il tempo di costruzione degli edifici attualmente in costruzione su un pianeta.', 'duration_label' => 'ora'],
    '1f7024c4f6493f0c589e1b00c76e6ced258c00e5' => ['name' => 'Slot flotte Oro', 'description' => '+6 Slot flotte extra', 'duration_label' => '12s 6g', 'extended_description' => 'Grazie a questo Slot flotte extra potrai far salpare un`altra flotta contemporaneamente. I generali competenti comprendono quanto sia importante incrementare la loro influenza ed estendere i loro domini nell`universo.'],
    '9b48e257cbef6c5df0f03a47cead7f9abda3d437' => ['name' => 'Guerriero (Alleanza)', 'description' => 'Velocità delle navi per i voli tra i giocatori dell`alleanza: +10%Ricerche militari: +1Ricerche di spionaggio: +1Accesso allo Spionaggio del sistema: la quantità di sonde di spionaggio selezionata viene inviata nel sistema per scansionarlo. È possibile impostare il corpo celeste da investigare, il tempo trascorso dall`ultimo attacco di spionaggio o l`attività desiderata dal giocatore.', 'duration_label' => 'Permanente', 'extended_description' => 'A volte i guerrieri più potenti non possono far altro che stringere un patto per dominare insieme la galassia. Le tecnologia di spionaggio disponibile per un`alleanza di questo tipo consente di identificare ancora più facilmente gli obiettivi degni di conquista. Insieme, la loro tecnologia è ancora più forte. E loro sono pronti a tutto.'],
    '0ad06bba14dfd0b576f1daef729a60753e2263c7' => ['name' => 'KRAKEN Oro (Forme di vita)', 'description' => 'Fa diminuire (-6o) il tempo di costruzione degli edifici attualmente in costruzione su un pianeta.', 'duration_label' => 'ora'],
    '5f194777c5b69d5c2a3c68e9e04a4cae9c28bcf2' => ['name' => 'KRAKEN Argento (Forme di vita)', 'description' => 'Fa diminuire (-2o) il tempo di costruzione degli edifici attualmente in costruzione su un pianeta.', 'duration_label' => 'ora'],
    '9cde936fabc5037617f8261955e7d3f2262eec69' => ['name' => 'NEWTRON Platino (Forme di vita)', 'description' => 'Fa diminuire (-1g) il tempo di ricerca delle ricerche attualmente attive su un pianeta.', 'duration_label' => 'ora'],
    '1c497ef926d674f2df9d96cfc58fe12f97cf4025' => ['name' => 'Avatar: Piccolo alieno', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Nuove forme di vita intelligente vengono continuamente scoperte nelle infinite distese dello spazio. Molti di loro sono completamente diversi dagli umani, con punti di forza e di debolezza unici.'],
    'ba3e6693f112986b7964c835bcac6ae201900e2f' => ['name' => 'NEWTRON Bronzo (Forme di vita)', 'description' => 'Fa diminuire (-30m) il tempo di ricerca delle ricerche attualmente attive su un pianeta.', 'duration_label' => 'ora'],
    '9879a36c42797a868416b13f07e033f664cabd70' => ['name' => 'NEWTRON Argento (Forme di vita)', 'description' => 'Fa diminuire di 2o il tempo di ricerca delle ricerche attualmente attive su un pianeta.', 'duration_label' => 'ora'],
    'fd3b0789b5dca99e9d5b251f8bae0760ce52dea6' => ['name' => 'Avatar: Augmented', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Il progresso non è più rallentato dai limiti del corpo umano. Gli impianti e altri miglioramenti tecnologici ti consentono di essere più veloce, più resistente e più forte degli altri.'],
    '7fe4cdb098685f8af827ca460a56e00ef46f5f05' => ['name' => 'NEWTRON Oro (Forme di vita)', 'description' => 'Fa diminuire (-6o) il tempo di ricerca delle ricerche attualmente attive su un pianeta.', 'duration_label' => 'ora'],
    'dc34fa00ba914ffab0031ac3f165e26f553d7809' => ['name' => 'Avatar: Lasercat', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Gatti e laser sono una combinazione inseparabile che ora può finalmente decorare il tuo profilo!'],
    '003db2a3d693c2d889864b76ad122b274bfd641b' => ['name' => 'Avatar: Senza peso', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'La prima passeggiata nello spazio è un grande momento per ogni giovane cosmonauta, indipendentemente dalla specie. Questa sensazione di guardare indietro al tuo piccolo pianeta natale mentre sei da solo tra le stelle rimarrà con te per il resto della tua vita.'],
    '8d514b69eb04a57495bab0c8f4b80f58294a7b17' => ['name' => 'Avatar: Gelido', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'I pianeti ghiacciati sono apprezzati per la loro buona resa di deuterio, ma a volte può essere necessario rafforzare le guardie, perché chissà cosa potrebbe nascondersi nascosto nel ghiaccio e nella neve...'],
    'c54d5a8f36f20373c5bb633a109241290b2e2a7a' => ['name' => 'Avatar: Guerrafondaio', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Alcuni imperatori spaziali duri come l`acciaio coltivano attentamente la loro immagine pericolosa. I supplicanti e coloro che rendono omaggio devono immediatamente vedere con chi hanno a che fare.'],
    'ac5bd99552a23733f7b0decac45094d5bfbfedac' => ['name' => 'Avatar: Ira consumante', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Alcuni sovrani spaziali diffondono paura e terrore ovunque vengano avvistate le loro flotte. Nessuno osa provocare la loro ira.'],
    '83c4e79697a264462e3ca2e8567307e7f1d7954b' => ['name' => 'Avatar: Cyberspace', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Molti cacciatori di fortuna che sperano di fare un buon affare tra le stelle sviluppano nel corso degli anni il proprio stile. Ciò aiuta a diffondere la loro fama e ad aumentare la loro reputazione anche in ambienti dubbi.'],
    '99f53568108115acac2d7f7425ee2ad76a6206b8' => ['name' => 'Avatar: Commander Kitty', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'I riflessi rapidi sono una risorsa per qualsiasi sovrano dello spazio, e un aspetto carino spesso dissuade dalla mente acuta tra le orecchie a punta.'],
    'da8b1dcf6a9defb45e456968d3c8587bf63a48b5' => ['name' => 'Avatar limitato: Orizzonte degli eventi', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'A quanto pare, il consiglio di lanciarsi temerariamente oltre orizzonti sconosciuti si applica solo in misura limitata all`esplorazione spaziale...'],
    '2d7de180f3f3d191982294d2f8c1cd7507e90cb4' => ['name' => 'Avatar: Retro Kitties', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Le leggende raccontano di un gatto molto carino che trascina dietro di sé arcobaleni mentre vola attraverso le distese infinite. Alcuni potrebbero spiegare queste storie parlando di un problema con il sistema di filtro del gas nella cabina di pilotaggio, ma chi lo sa...'],
    'c70f11e9543100622e3ef3bdcd57099a63f148bf' => ['name' => 'Avatar: Destino', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Innumerevoli conflitti in tanti mondi diversi sono stati combattuti con dadi a venti facce. Ma i lati di questo dado sono vuoti: quale destino segnerà?'],
    '69719df021ec40424225f22e2edca15b799401a5' => ['name' => 'Avatar limitato: Pilota stellare', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Sono i membri dell`equipaggio più capaci, i piloti dai riflessi più pronti e le menti più brillanti a portare l`eredità dell`umanità nella galassia sconfinata.'],
    'facb9419f24c4a1fbff7dc29376c3f57c6204c1c' => ['name' => 'Avatar limitato: Androide', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'È proprio negli ambienti più inospitali per la vita umana che equipaggi completamente meccanici si rivelano più vantaggiosi. Innanzitutto, serve meno spazio di carico per le razioni; inoltre, grazie ai sistemi di ricarica rapida, il riposo notturno nella postazione di carica dura meno del sonno tradizionale e, dall`introduzione di sistemi di batterie migliori, nemmeno sui pianeti di ghiaccio tocca più restare appesi in modo indecoroso al cavo di ricarica.'],
    '74bf9741209dc8ef4f9996b8b2b7ca59001ea3a8' => ['name' => 'Avatar limitato: Tartaruga stellare', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Benché l`esistenza di tartarughe stellari venga generalmente messa in dubbio nei circoli scientifici, le voci persistono con insistenza. I resoconti di avvistamenti collegano regolarmente questa specie a pachidermi, corpi celesti piatti e altre bizzarrie assortite.'],
    '07a4b64949fcc593435cfaa9184290af96ffdc29' => ['name' => 'Avatar limitato: Fabbro del destino', 'description' => 'Seleziona questo avatar nel tuo profilo giocatore per usarlo e aggiungere un tocco personale al tuo profilo. Questo item viene attivato globalmente per tutti gli universi del tuo account. Ricorda che la sincronizzazione tra gli universi può richiedere un certo tempo.', 'duration_label' => 'Permanente', 'extended_description' => 'Ogni imperatore tiene tra le mani il destino del proprio Impero galattico. Sarai tu a forgiarne il fato, poiché la tua sorte e la tua lungimiranza decideranno tra trionfo e sconfitta.'],
